  "output": ".radar-brand { display: flex; align-items: center; gap: 12px; line-height: 1.05; }
.radar-brand-title { font-family: var(--radar-mono); font-size: 13px; font-weight: 600; letter-spacing: 3px; color: var(--radar-muted); white-space: nowrap; }
.radar-brand-ring { fill: none; stroke: var(--radar-accent); stroke-width: 1.5; }
.radar-brand-ring--inner { stroke: rgba(59, 130, 246, 0.5); stroke-width: 1.2; }
.radar-brand-beam { stroke: var(--radar-accent); stroke-width: 2; }
.radar-brand-blip { fill: var(--radar-amber); }
.radar-feed-pill { display: flex; align-items: center; gap: 8px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 999px; font-family: var(--radar-mono); font-size: 12px; letter-spacing: 1px; white-space: nowrap; }
.radar-feed-pill--stale { border-color: var(--radar-amber); color: var(--radar-stale-ink); }
.radar-feed-pill--stale .radar-live-dot { background: var(--radar-amber); box-shadow: 0 0 10px var(--radar-amber); }
.radar-live-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--radar-accent); box-shadow: 0 0 10px var(--radar-accent); animation: radar-livedot 1.2s infinite; }
.radar-clock { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.1; font-family: var(--radar-mono); }
.radar-clock--utc .radar-clock-time { color: var(--radar-dim); }
.radar-clock-label { font-size: 10px; letter-spacing: 2px; color: var(--radar-dim); }
.radar-head-button { min-height: 36px; padding: 6px 12px; border: 1px solid rgba(59, 130, 246, 0.35); border-radius: 8px; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-screen:fullscreen .radar-head-button { display: none; }
.radar-modes { display: inline-flex; align-items: stretch; margin-left: auto; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; overflow: hidden; background: transparent; }
.radar-modes .radar-mode { min-height: 36px; padding: 6px 14px; border: 0; border-radius: 0; background: transparent; color: var(--radar-muted); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; line-height: 1.25; cursor: pointer; }
.radar-modes .radar-mode + .radar-mode { border-left: 1px solid rgba(59, 130, 246, 0.3); }
.radar-modes .radar-mode[aria-pressed="true"] { background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); }
.radar-modes .radar-mode:focus-visible { outline: 2px solid var(--radar-accent); outline-offset: -2px; }
.radar-days { display: flex; align-items: center; gap: 6px; font-family: var(--radar-mono); font-size: 13px; letter-spacing: 1px; }
.radar-day-step { min-width: 36px; min-height: 36px; border: 1px solid rgba(59, 130, 246, 0.3); border-radius: 8px; background: transparent; color: var(--radar-muted); cursor: pointer; }
.radar-day-step:disabled { opacity: 0.35; cursor: default; }
.radar-day-label { min-width: 92px; text-align: center; font-weight: 600; color: var(--radar-ink); }
.radar-day-live { min-height: 36px; padding: 6px 12px; border: 1px solid var(--radar-accent); border-radius: 8px; background: rgba(59, 130, 246, 0.14); color: var(--radar-ink); font-family: var(--radar-mono); font-size: 12px; font-weight: 600; letter-spacing: 1.5px; cursor: pointer; }
.radar-feed-pill--replay { border-color: var(--radar-amber); background: rgba(255, 181, 71, 0.1); color: var(--radar-stale-ink); }
.radar-tenant { padding-left: 16px; border-left: 1px solid var(--radar-line); font-size: 13px; font-weight: 600; letter-spacing: 1px; color: var(--radar-muted); }
/* a narrower screen drops what it can read elsewhere: the tenant (console header), the subtitle, then the UTC clock */
@media (max-width: 1280px) { .radar-tenant { display: none; } }
@media (max-width: 1040px) { .radar-clock--utc { display: none; } .radar-head { gap: 14px; padding: 10px 16px; } }

.radar-main { flex-grow: 1; display: grid; grid-template-columns: minmax(340px, 470px) minmax(0, 1fr); gap: clamp(28px, 4vw, 72px); padding: 24px 32px 28px; min-height: 0; }
@media (max-width: 1040px) { .radar-main { grid-template-columns: minmax(0, 1fr); gap: 28px; padding: 18px 16px 20px; } }
